std::set<int> A = {10, 20, 30, 40};
std::set<int> B = {20, 40, 50, 60};

// Result stores elements in A but not in B: {10, 30}
std::vector<int> difference_elements;

std::set_difference(
    A.begin(), A.end(),
    B.begin(), B.end(),
    std::back_inserter(difference_elements)
);

// Note: Requires #include <algorithm>, <set>, <vector>, <iterator>
